const lockLibraryOwner = `-- name: LockLibraryOwner :exec

SELECT pg_advisory_xact_lock((3::bigint << 32) + $1::bigint)
`

// 私有题库、成员、题目、题目标签、题目修订与题库回收站的读写。
//
// 容量判定一律在事务内完成（C-21）：锁定 → 计数 → 判定 → 写入。
// 题目读取时联出来源提示词的可见性要素，使「引用题是否对当前身份可见」
// 能在应用层用与提示词同一套谓词判定（C-20）。
// 锁键 = 命名空间 << 32 + 对象标识。命名空间：1 收藏夹、2 统计重算、3 题库。
// 高位置命名空间使不同域的同号对象不再互相阻塞。
func (q *Queries) LockLibraryOwner(ctx context.Context, ownerID int64) error {
	_, err := q.db.Exec(ctx, lockLibraryOwner, ownerID)
	return err
}

