const reorderLibraryQuestions = `-- name: ReorderLibraryQuestions :exec
UPDATE library_questions AS q
SET sort_order = data.ord, updated_at = now()
FROM (
    SELECT t.id AS id, ($2::int[])[t.ordinality] AS ord
    FROM unnest($3::bigint[]) WITH ORDINALITY AS t(id, ordinality)
) AS data
WHERE q.id = data.id AND q.library_id = $1 AND q.deleted_at IS NULL
`

type ReorderLibraryQuestionsParams struct {
	LibraryID int64
	Orders    []int32
	Ids       []int64
}

// 按给定顺序重排题目：orders 与 ids 按位置对应，只影响本库内未删除的题目。
// 用 WITH ORDINALITY 把两个数组按下标配对，避免逐条 UPDATE 在一个事务里往返多次。
func (q *Queries) ReorderLibraryQuestions(ctx context.Context, arg ReorderLibraryQuestionsParams) error {
	_, err := q.db.Exec(ctx, reorderLibraryQuestions, arg.LibraryID, arg.Orders, arg.Ids)
	return err
}

